/***********************************************************************************************************
 * css reset for browser default rules and MediaWiki internal rules
 ***********************************************************************************************************/
* {
  outline: 0;
}

table {
  display: table;
  white-space: unset; /* be set to `nowrap` in MW internal css */
}

html {
  font-size: 16px; /* reset rem size */
}

body {
  overflow-y: unset;
}

body, code {
  background: none;
}

pre {
  margin: 0;
}

h1, h2, h3, h4, h5, h6 {
  padding: 0;
  border: 0 solid transparent;
}

/***********************************************************************************************************
 * Base CSS styles for both interface and content box: font, color, etc.
 ***********************************************************************************************************/
/* Font */
html, body {
  font-family: var(--font-family);
  color: var(--theme-text-color);
}

/* Text color */
#content {
  color: var(--theme-text-color);
}

html {
  background: var(--theme-site-background);
  /* Always show a scroll bar on short pages. This way, the page background
   * size won't change when expanding/collapsing sections in the sidebar. */
  overflow-y: scroll;
}

body {
  font-size: var(--font-size);
  line-height: var(--line-height);
}

/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/core/+/refs/heads/REL1_43/resources/src/mediawiki.skinning/elements.less#155 */
ul, ol {
  margin: 2px 0 2px 1.5em;
}

ul {
  list-style-image: none;
}

li {
  margin: 0 0 2px 0;
}

