}

/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/core/+/refs/heads/REL1_43/resources/src/mediawiki.interface.helpers.styles/linker.styles.less#81 */
/* "| contribs |" links for users with no edits, e.g. on Special:AbuseLog/x */
.mw-usertoollinks-contribs-no-edits, .mw-usertoollinks-contribs-no-edits:visited, .mw-usertoollinks-contribs-no-edits:hover, .mw-usertoollinks-contribs-no-edits:active {
  /* (:hover and :active are not in the base stylesheet, but are needed 
   * here to override the generic "a:hover" and "a:active" rules) */
