/********* [[Special:NewPages]] *********/
/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/core/+/refs/heads/REL1_43/resources/src/mediawiki.special/newpages.less#13 */
.not-patrolled {
  background-color: var(--oouihelper--yellow);
}

/********* [[Special:Search]] *********/
/* Search result page */
/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/core/+/refs/heads/REL1_43/resources/src/mediawiki.special.search.styles.less */
.mw-search-form-wrapper {
  font-size: 1em;
}

.mw-search-form-wrapper .mw-search-visualclear {
  display: none;
}

.mw-search-result-data {
  color: var(--theme-text-color-note);
}

.mw-search-profile-tabs {
  background: none;
  border: 0;
  margin: 1em 0;
}

.search-types {
  width: 100%;
  float: none;
  padding: 0;
}
.search-types li {
  float: none;
  display: inline-block;
  vertical-align: middle;
}
.search-types .current a {
  color: var(--theme-text-color);
}
.search-types ul li.current {
  background: var(--theme-highlight-background);
  border-radius: 4px;
  overflow: hidden;
}
.search-types + div {
  display: none;
}

.results-info {
  color: var(--theme-text-color-note);
  font-size: 1em;
  padding: 0 0 0 3em;
  white-space: nowrap;
  text-align: right;
  flex: 1 1 auto;
}

#mw-search-top-table {
  display: flex;
  align-items: center;
}

#mw-searchoptions {
