/********* Extension:SyntaxHighlight *********/
/* (formerly known as "SyntaxHighlight_GeSHi") */
/* Highlight fields inside code class (e.g. Template:Code) */
code.mw-highlight {
  background: var(--theme-page-background-color);
  color: var(--theme-text-color);
}

/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/extensions/SyntaxHighlight_GeSHi/+/refs/heads/REL1_43/modules/pygments.copy.less */
.mw-highlight-copy--bound button:first-child {
  /* Hide the "copy" button if the code is empty. The button is added
   * after the code, so if it's the first child, then there is no code. */
  display: none;
}

/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/extensions/SyntaxHighlight_GeSHi/+/refs/heads/REL1_43/modules/pygments.generated.css#8 */
.mw-highlight {
  background: inherit;
}

/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/extensions/SyntaxHighlight_GeSHi/+/refs/heads/REL1_43/modules/pygments.wrapper.less#18 */
.mw-highlight pre {
  margin-top: 1em;
  background: #282828 !important;
  color: #fff !important;
  overflow: auto; /* scroll if needed */
}

/* overwriting styles from here:
 * https://gerrit.wikimedia.org/r/plugins/gitiles/mediawiki/extensions/SyntaxHighlight_GeSHi/+/refs/heads/master/modules/pygments.generated.css */
.mw-highlight, .kw1 {
  color: #FFFFFF;
  font-weight: bold;
}

.mw-highlight .nf {
  color: aqua;
}

/* Operators */
.mw-highlight .p,
.mw-highlight .o {
  color: #fff;
  font-weight: bold;
}

/* Comments */
.mw-highlight .c {
  color: #8d9e6b;
  font-weight: bold;
}

/* HTML Tags */
.mw-highlight .nt {
  color: #bfe431;
}

/* IDs */
.mw-highlight .nn {
  color: #a8a8ff;
}

/* Classes */
.mw-highlight .nc {
  color: #7676ff;
}

/* Pseudo-classes */
.mw-highlight .nd {
  color: #cf82ff;
}

/* Properties */
.mw-highlight .k,
.mw-highlight .kp {
  color: #fff;
  font-weight: normal;
}

/* Keywords */
.mw-highlight .nb {
  color: #ff5858;
}

/* Text values, strings */
.mw-highlight .kc,
.mw-highlight .s1,
.mw-highlight .s2,
.mw-highlight .sx,
.mw-highlight .n {
  color: #00c6d2;
}

/* Numeric values */
.mw-highlight .mi,
.mw-highlight .mf {
  color: #60feff;
  font-weight: bold;
}

/* Units */
.mw-highlight .kt {
  color: #ff3f85;
  font-weight: bold;
}

/* #Color values */
.mw-highlight .mh {
  color: #b2d241;
}

/* !important */
.mw-highlight .cp {
  color: #F37F20;
}

/* JS generic */
.mw-highlight .nx {
  color: #a8a8ff;
}

.mw-highlight .nv {
  color: #fff;
}

/* Highlighted lines */
.mw-highlight .hll {
  background-color: #50503e;
}

