}
.npc.infobox .drops.items li.notebox {
  display: block;
  text-align: center;
  padding: 0;
}
.npc.infobox .drops.items li.notebox > div {
  text-align: center;
  border-width: 1px;
  border-style: dashed;
  border-color: rgba(var(--theme-border-color--rgb), 0.8);
  border-radius: 3px;
  margin: 3px auto;
  padding: 2px 0;
