}

/**** old navbox: may be still used on language wikis ****/
/* subtemplates:
 * [[Template:Navbox/end]]
 * [[Template:Navbox/h1]]
 * [[Template:Navbox/h2]]
 * [[Template:Navbox/start]]
 * [[Template:Navbox/v.d.e]]
 */
.navbox {
  background: var(--theme-highlight-background);
  background-size: 100%;
  border-width: 1px;
  border-style: solid;
  border-color: var(--theme-box-border-color-inner);
  border-radius: var(--theme-box-border-radius-inner);
  box-sizing: border-box;
  padding: 6px;
  margin: 0.5em auto;
  width: 100%;
  max-width: 1800px;
  position: relative;
  clear: both;
}
.navbox .i {
  padding: 1px 0;
}
.navbox > .header {
  background: var(--theme-highlight-background);
  background-size: 100%;
  border-width: 1px;
  border-style: solid;
  border-color: var(--theme-box-border-color-inner);
  border-radius: var(--theme-box-border-radius-inner);
  text-align: left;
  font-size: 16px;
  font-weight: bold;
  line-height: 2;
  min-height: 1em;
  padding: 4px 70px 4px 6px;
}
.navbox > .vde {
  position: absolute;
  right: 10px;
  top: calc(2rem + 2px);
  font-size: 9px;
  line-height: 1;
  color: var(--theme-text-color-note);
}
.navbox .table > div > .title,
.navbox .table > div > .h1,
.navbox .table > div > .h2 {
  background: var(--theme-highlight-background);
  background-size: 100%;
  border-width: 1px;
  border-style: solid;
  border-color: var(--theme-box-border-color-inner);
  border-radius: var(--theme-box-border-radius-inner);
}
.navbox > .mw-collapsible-toggle {
  position: absolute;
  line-height: 1;
  right: 10px;
  top: 10px;
  font-size: 12px;
}
.navbox > .mw-collapsible-toggle > .mw-collapsible-bracket {
  display: none;
}
.navbox > .mw-collapsible-toggle:before {
  content: "";
  vertical-align: middle;
  display: inline-block;
  width: 5px;
  height: 5px;
  transform: rotate(45deg);
  position: relative;
  left: -3px;
  border-left: 2px solid var(--theme-link-color);
  border-top: 2px solid var(--theme-link-color);
  border-right: 0;
  border-bottom: 0;
  top: 1px;
}
.navbox > .mw-collapsible-toggle:after {
  content: "";
}
.navbox > .mw-collapsible-toggle.mw-collapsible-toggle-collapsed:before {
  border-left: 0;
  border-top: 0;
  border-right: 2px solid var(--theme-link-color);
  border-bottom: 2px solid var(--theme-link-color);
  top: -2px;
}
.navbox > .content {
  text-align: left;
  padding: 6px 6px 0;
}
.navbox > .content .dotlist + .dotlist {
  margin-top: 0.5em;
}
.navbox > .content > .dotlist + .dotlist {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--theme-body-text-color--hover);
}
.navbox .navbox {
  /* nested navbox */
  border: 0;
  padding: 0;
  width: auto;
  margin: 0 -6px 6px -6px;
}
.navbox .navbox:last-child {
  margin: 0 -6px;
}
.navbox .navbox > .header {
  font-size: 14px;
  padding: 0 64px 0 6px;
}
.navbox .navbox > .mw-collapsible-toggle {
  right: 4px;
  top: 4px;
  font-size: 10px;
}
.navbox .navbox > .mw-collapsible-toggle:before {
  width: 3px;
  height: 3px;
  border-left: 1px solid var(--theme-link-color);
  border-top: 1px solid var(--theme-link-color);
  border-right: 0;
  border-bottom: 0;
  top: 1px;
}
.navbox .navbox > .mw-collapsible-toggle.mw-collapsible-toggle-collapsed:before {
  border-left: 0;
  border-top: 0;
  border-right: 1px solid var(--theme-link-color);
  border-bottom: 1px solid var(--theme-link-color);
  top: -1px;
}
.navbox .h1 {
  font-weight: bold;
  margin-top: 0.5em;
  margin-bottom: 0.25em;
  line-height: 1.5;
}
.navbox .h1::after {
  content: "";
  display: block;
  margin: auto auto auto 0;
  width: 5em;
  height: 0;
  border-bottom: 2px solid var(--theme-box-border-color);
}
.navbox .h1 + .h2 {
  margin-top: 0.5em;
}
.navbox .table > div:first-child .h1,
.navbox .content > .h1:first-child {
  margin-top: auto;
}
.navbox .h2 {
  font-weight: bold;
  line-height: 1.5;
  margin-top: 0.25em;
  font-size: 12px;
}
.navbox .h2 + .h3 {
  margin-top: 0.5em;
}
.navbox .h3 {
  font-size: 10px;
  font-weight: bold;
  line-height: 1.5;
}
@media (max-width: 599px) {
  .navbox .table > div > .title::after,
  .navbox .table > .dotlist > .title::after {
    content: ":";
    margin-right: 0.25em;
  }
}
@media (min-width: 600px) {
  .navbox .table {
    display: table;
    text-align: left;
    margin: -5px -7px -1px -7px;
  }
  .navbox .table > div {
    display: table-row;
  }
  .navbox .table > div > * {
    display: table-cell;
    padding: 4px 7px;
    vertical-align: middle;
    box-shadow: inset 0 0 0 1px var(--theme-page-background-color);
  }
  .navbox .table > div > .title,
  .navbox .table > div > .h1,
  .navbox .table > div > .h2 {
    background: var(--theme-highlight-background);
    text-align: right;
    line-height: 1.1;
    /*width: max-content;*/
  }
  .navbox .table > div > .title .eil,
  .navbox .table > div > .h1 .eil,
  .navbox .table > div > .h2 .eil {
    white-space: normal;
  }
  .navbox .table > div > .title::after,
  .navbox .table > div > .h1::after {
    display: none;
  }
  .navbox .table .table {
    display: table;
    padding: 0;
    margin: 0 -1px 0 0;
  }
  .navbox .table .cell {
    padding: 0;
  }
  .navbox .table .cell > .dotlist {
    padding: 4px 7px;
  }
}

/********* [[Template:Coin]], [[Template:Pc]], [[Template:Gc]], [[Template:Sc]], [[Template:Dm]] *********/
