}
.coin .pc::after, .coin .gc::after, .coin .sc::after, .coin .cc::after, .coin .dm::after {
  content: "";
  display: inline-block;
  width: 12px;
  height: 16px;
  margin: -3px 2px auto;
  vertical-align: middle;
