  --theme-widget-shadow: 0px 0px 15px 0px rgba(10,10,10, 0.7);
  --theme-widget-border-color: rgba(255,255,255, 0.1) rgba(13, 4, 2, 0.2) rgba(13, 4, 2, 0.2) rgba(255,255,255, 0.1);
  --theme-widget-border-radius: 6px;
