  --oouihelper--themerelated-lightest: #e6dbcb;
  --oouihelper--themerelated-darker: #785f3a;
  --oouihelper--themerelated-darkest: #342919;
  --oouihelper--themerelated-disabled: rgba(230, 219, 203, 0.25);
